// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;

    function setUp() public {
        c = new EBU();
    }

    function testFuzz_property(address from, address recipient, uint256 amount) public {
        vm.assume(recipient != address(0));
        vm.assume(amount != uint256(uint160(recipient)));

        Recorder rec = new Recorder();

        address[] memory tos = new address[](1);
        tos[0] = recipient;
        uint256[] memory v = new uint256[](1);
        v[0] = amount;

        bool ok; try c.transfer(from, address(rec), tos, v) { ok = true; } catch { ok = false; }
        assertTrue(ok, "transfer must not revert");

        (address seenRecipient, uint256 seenAmount) = rec.first();
        assertTrue(seenRecipient == recipient && seenAmount == amount, "external call must carry (_tos[i], v[i]) in that order");
    }
}

contract Recorder {
    address private __recipient;
    uint256 private __amount;
    bool private __set;

    function transferFrom(address, address to, uint256 amt) external returns (bool) {
        if (!__set) {
            __set = true;
            __recipient = to;
            __amount = amt;
        }
        return true;
    }

    function first() external view returns (address, uint256) {
        return (__recipient, __amount);
    }
}
